css:
/* Owner-approved SDCE print design (2026-11-09): the standard Frappe print look. Colours are the Frappe v16
   print greys as literal hex (no CSS variables, @import or remote fonts: wkhtmltopdf's old Qt WebKit drops
   them): text #171717, secondary #525252, labels #7c7c7c, table header #f3f3f3, borders #d1d8dd, light
   separators #ededed, heading underline #aaa. */
/* geometry: without this override Frappe's default .print-format padding
   shifts RTL cell text across borders in wkhtmltopdf (same lesson as the
   monthly card format) */
.print-format { padding: 0 !important; margin: 0 !important; max-width: 100% !important; width: 100% !important; }
.print-format-gutter { padding: 0 !important; }

/* text-rendering auto: frappe's print bundle sets optimizeLegibility on body,
   which makes Qt draw RTL lines wider than it measures them (text crosses cell
   borders); resetting it here fixes the geometry. */
.cpf { text-rendering: auto; font-family: 'Noto Sans Arabic', 'Noto Sans', 'Segoe UI', Tahoma, sans-serif; color: #171717; font-size: 9.5pt; line-height: 1.45; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.cpf table { width: 100%; border-collapse: collapse; }
/* old Qt WebKit (wkhtmltopdf) follows CSS direction, not the dir attribute, and has no text-align: start */
.cpf.rtl { direction: rtl; text-align: right; }
.cpf.ltr { direction: ltr; text-align: left; }

.cpf .co { font-size: 10pt; font-weight: bold; color: #525252; margin: 0 0 1px; }
.cpf .h { border-bottom: 1px solid #aaa; margin: 0 0 3mm; padding-bottom: 3px; }
.cpf .h h2 { margin: 0; font-size: 16pt; font-weight: bold; color: #171717; line-height: 1.3; }
.cpf .h h2 .st { color: #7c7c7c; font-size: 11pt; }

.cpf .meta { table-layout: fixed; margin-bottom: 3mm; }
.cpf .meta td { border: none !important; padding: 0.8mm 1mm !important; vertical-align: top; color: #171717; word-wrap: break-word; }
.cpf .meta td.ml { width: 17%; font-weight: bold; color: #7c7c7c; }
.cpf.rtl .meta td { text-align: right; }
.cpf.ltr .meta td { text-align: left; }

/* rows: #f3f3f3 header, 1px #d1d8dd borders, centred cells; text follows the page direction, numbers read
   left to right and are right-aligned so the decimals line up, row numbers and counts are centred */
.cpf .rows { table-layout: fixed; border: 1px solid #d1d8dd; }
.cpf .rows th, .cpf .rows td { border: 1px solid #d1d8dd !important; padding: 1.2mm 2mm !important; vertical-align: middle !important; word-wrap: break-word; }
.cpf .rows th { background: #f3f3f3 !important; color: #525252; font-weight: bold; text-align: center; }
.cpf.rtl .rows td.t { text-align: right; }
.cpf.ltr .rows td.t { text-align: left; }
.cpf .rows td.c { text-align: center; direction: ltr; unicode-bidi: embed; white-space: nowrap; }
.cpf .rows td.num { text-align: right; direction: ltr; unicode-bidi: embed; white-space: nowrap; }

/* totals: label/value lines right under the last (amount) column, at the end side of the page;
   one weight per cell (Qt overlaps a regular+bold Arabic run pair) */
.cpf .tot { width: 45%; margin-top: 2mm; page-break-inside: avoid; }
.cpf.rtl .tot { margin-left: 0; margin-right: auto; }
.cpf.ltr .tot { margin-left: auto; margin-right: 0; }
.cpf .tot th { color: #525252; font-weight: bold; padding: 0 1.5mm 1mm !important; border-bottom: 1px solid #aaa !important; }
.cpf .tot td { padding: 0.8mm 1.5mm !important; border-bottom: 1px solid #ededed !important; vertical-align: middle !important; }
.cpf .tot td.k { width: 55%; color: #525252; }
.cpf .tot td.v { direction: ltr; unicode-bidi: embed; font-weight: bold; white-space: nowrap; }
.cpf.rtl .tot th, .cpf.rtl .tot td.k { text-align: right; }
.cpf.ltr .tot th, .cpf.ltr .tot td.k { text-align: left; }
.cpf.rtl .tot td.v { text-align: left; }
.cpf.ltr .tot td.v { text-align: right; }
.cpf .tot tr.last td { font-size: 10.5pt; font-weight: bold; color: #171717; border-top: 1px solid #aaa !important; border-bottom: none !important; }

.cpf .words { margin-top: 2mm; color: #525252; }
.cpf .words .ml { font-weight: bold; color: #7c7c7c; }
.cpf .stmt { margin-top: 4mm; color: #525252; }

.cpf .sign { margin-top: 10mm; table-layout: fixed; page-break-inside: avoid; }
.cpf .sign td { text-align: center !important; border: none !important; padding: 0 6mm !important; vertical-align: top; }
.cpf .sign .l { border-top: 1px solid #999; margin: 10mm 8% 1.2mm; height: 0; }
.cpf .sign .t { font-weight: bold; color: #525252; }
.cpf .sign .n { color: #171717; min-height: 4mm; }

html:
{%- set L = doc.meta.get_label -%}
{%- set company_name = (frappe.db.get_value("Company", doc.company, "company_name") or doc.company) if doc.company else "" -%}
{#- the page direction follows the print language (frappe.utils.jinja_globals.is_rtl) -#}
{#- right-to-left for ar/he/fa/ps and, in CARD, Urdu (card.print_utils.card_print_is_rtl, read at render time) -#}
{%- set dir = "rtl" if card_print_is_rtl() else "ltr" -%}
{%- set worker = doc.employee_name or doc.employee -%}
{%- set mate = (frappe.db.get_value("Employee", doc.to_employee, "employee_name") or doc.to_employee) if doc.to_employee else "" -%}
{%- set issuer_user = doc.handed_by or frappe.session.user -%}
{%- set issuer = frappe.db.get_value("User", issuer_user, "full_name") or issuer_user -%}
{#- who gives and who takes the tool in this movement -#}
{%- if doc.movement == "Return" -%}
  {%- set giver, taker = worker, issuer -%}
{%- elif doc.movement == "Transfer" -%}
  {%- set giver, taker = worker, mate -%}
{%- else -%}
  {%- set giver, taker = issuer, worker -%}
{%- endif -%}
{%- set project_disp = (frappe.db.get_value("Project", doc.project, "project_name") or doc.project) if doc.project else "" -%}
{%- set machine_disp = (frappe.db.get_value("Card Equipment", doc.card_equipment, "equipment_name") or doc.card_equipment) if doc.card_equipment else "" -%}
<div class="cpf {{ dir }}" dir="{{ dir }}">
  {% if company_name %}<div class="co">{{ company_name|e }}</div>{% endif %}
  <div class="h"><h2>{{ _("Tool Handover Receipt") }} <span class="st">— {{ _(doc.movement)|e }}{% if doc.docstatus == 2 %} {{ _("(Cancelled)") }}{% endif %}</span></h2></div>
  <table class="meta">
    <tr>
      <td class="ml">{{ _("Document no.") }}</td><td><span dir="ltr">{{ doc.name|e }}</span></td>
      <td class="ml">{{ _(L("date")) }}</td><td><span dir="ltr">{{ frappe.utils.formatdate(doc.date) if doc.date else "" }}</span></td>
    </tr>
    <tr>
      <td class="ml">{{ _(L("employee")) }}</td><td>{{ worker|e }} <span dir="ltr">({{ doc.employee|e }})</span></td>
      {%- if doc.to_employee %}
      <td class="ml">{{ _(L("to_employee")) }}</td><td>{{ mate|e }} <span dir="ltr">({{ doc.to_employee|e }})</span></td>
      {%- else %}
      <td class="ml">{{ _(L("warehouse")) }}</td><td>{{ (doc.warehouse or "")|e }}</td>
      {%- endif %}
    </tr>
    <tr>
      <td class="ml">{{ _(L("card_equipment")) }}</td><td>{{ machine_disp|e }}</td>
      <td class="ml">{{ _(L("project")) }}</td><td>{{ project_disp|e }}</td>
    </tr>
    {%- if doc.notes %}
    <tr><td class="ml">{{ _(L("notes")) }}</td><td colspan="3">{{ doc.notes|e }}</td></tr>
    {%- endif %}
  </table>
  <table class="rows">
    <tr>
      <th style="width:7%;">#</th>
      <th>{{ _(L("item_code")) }}</th>
      <th style="width:16%;">{{ _(L("qty")) }}</th>
      <th style="width:26%;">{{ _(L("serial_no")) }}</th>
    </tr>
    <tr>
      <td class="c">1</td>
      <td class="t">{{ (doc.item_name or doc.item_code)|e }} <span dir="ltr">({{ doc.item_code|e }})</span></td>
      <td class="num">{{ doc.get_formatted("qty") }}</td>
      <td class="c">{{ (doc.serial_no or "")|e }}</td>
    </tr>
  </table>
  <div class="stmt">{{ _("The receiver confirms receiving the tool above in good condition and is responsible for it until it is returned or handed over.") }}</div>
  <table class="sign"><tr>
    <td><div class="l"></div><div class="t">{{ _("Handed over by") }}</div><div class="n">{{ giver|e }}</div></td>
    <td><div class="l"></div><div class="t">{{ _("Received by") }}</div><div class="n">{{ taker|e }}</div></td>
  </tr></table>
</div>
